  margin-bottom: 3rem;
}

.about-text {
  font-family: var(--sans);
  font-size: clamp(1.05rem, 1.8vw, 1.25rem);
  line-height: 1.85;
  color: var(--text);
  max-width: 800px;
}

.about-text p {
  margin-bottom: 1.5rem;
