  font-family: var(--serif);
  font-size: 1.5rem;
  font-style: italic;
  margin-top: 3rem;
  color: var(--text);
}

.founder-letter .letter-body p:first-of-type::first-letter {
  font-family: var(--serif);
  font-size: 4rem;
  float: left;
  line-height: 0.8;
  padding-right: 0.5rem;
  padding-top: 0.15rem;
  font-weight: 700;
  color: var(--accent-terracotta);
}

