  padding-left: 3rem;
  padding-right: 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-title {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  margin-bottom: 3rem;
  color: var(--text);
}

.philosophy-body {
  max-width: 700px;
  font-size: 1.1rem;
  line-height: 1.9;
}

.philosophy-body p {
  margin-bottom: 1.5rem;
}

.section-divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 3rem;
}

.section-divider hr {
  border: none;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

.services-section {
  padding: 4rem 3rem 6rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-question {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 500;
  font-style: italic;
  margin-bottom: 4rem;
  color: var(--text);
