  margin-bottom: 3.5rem;
  max-width: 750px;
}

.service-item h3 {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text);
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.85;
  color: var(--text-secondary);
}

