  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay a {
  font-family: var(--serif);
  font-size: clamp(2rem, 8vw, 4rem);
  font-weight: 600;
  color: var(--text);
  transform: translateY(30px);
  opacity: 0;
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-overlay.active a {
  transform: translateY(0);
  opacity: 1;
}

.mobile-overlay.active a:nth-child(1) { transition-delay: 0.1s; }
.mobile-overlay.active a:nth-child(2) { transition-delay: 0.15s; }
.mobile-overlay.active a:nth-child(3) { transition-delay: 0.2s; }
.mobile-overlay.active a:nth-child(4) { transition-delay: 0.25s; }
.mobile-overlay.active a:nth-child(5) { transition-delay: 0.3s; }

/* ============================
   HERO
   ============================ */

.hero {
  min-height: 60vh;
  display: flex;
  align-items: flex-end;
  padding: 0 3rem;
  padding-top: 8rem;
  padding-bottom: 4rem;
}

.hero-title {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 900px;
  color: var(--text);
}

/* ============================
   MEDIA SHOWCASE
   ============================ */

.media-showcase {
  padding: 2rem 3rem 4rem;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr 1fr;
  gap: 1rem;
  width: 100%;
}

.media-block {
  width: 100%;
  border-radius: 4px;
}

.media-block--tall {
  height: 420px;
}

.media-block--medium {
  height: 420px;
}

.media-block--terracotta { background-color: var(--accent-terracotta); }
.media-block--sage { background-color: var(--accent-sage); }
.media-block--sand { background-color: var(--accent-sand); }

/* ============================
   CLIENT MARQUEE
   ============================ */

.client-marquee {
  padding: 4rem 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.1);
  border-bottom: 1px solid rgba(26, 26, 26, 0.1);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  margin: 1rem 0;
}

.marquee-track {
  display: flex;
  animation: marquee-left 30s linear infinite;
  will-change: transform;
}

.marquee-row:nth-child(2) .marquee-track {
  animation: marquee-right 35s linear infinite;
}

.marquee-row:nth-child(3) .marquee-track {
  animation: marquee-left 32s linear infinite;
}

.marquee-item {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 500;
  padding: 0 1.5rem;
  color: var(--text);
  flex-shrink: 0;
}

.marquee-separator {
  font-size: clamp(1rem, 2vw, 1.5rem);
  padding: 0 0.5rem;
  color: var(--text-secondary);
  opacity: 0.4;
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ============================
   ABOUT SECTION
   ============================ */

.about-section {
  padding: 6rem 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-label {
  font-family: var(--sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: 3rem;
}

.about-text {
  font-family: var(--sans);
  font-size: clamp(1.05rem, 1.8vw, 1.25rem);
  line-height: 1.85;
  color: var(--text);
  max-width: 800px;
}

.about-text p {
  margin-bottom: 1.5rem;
}

/* ============================
   FOUNDER LETTER (neweno)
   ============================ */

.founder-letter {
  padding-top: 10rem;
  padding-bottom: 6rem;
  padding-left: 3rem;
  padding-right: 3rem;
  max-width: 720px;
  margin: 0 auto;
}

.founder-letter .page-label {
  font-family: var(--sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: 4rem;
}

.founder-letter .letter-greeting {
  font-family: var(--serif);
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 500;
  line-height: 1.2;
  margin-bottom: 3rem;
  color: var(--text);
}

.founder-letter .letter-body p {
  font-family: var(--sans);
  font-size: 1.1rem;
  line-height: 2;
  margin-bottom: 1.8rem;
  color: var(--text);
}

.founder-letter .letter-signature {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-style: italic;
  margin-top: 3rem;
  color: var(--text);
}

.founder-letter .letter-body p:first-of-type::first-letter {
  font-family: var(--serif);
  font-size: 4rem;
  float: left;
  line-height: 0.8;
  padding-right: 0.5rem;
  padding-top: 0.15rem;
  font-weight: 700;
  color: var(--accent-terracotta);
}

/* ============================
   SERVICES PAGE
   ============================ */

.philosophy-section {
  padding-top: 10rem;
  padding-bottom: 4rem;
  padding-left: 3rem;
  padding-right: 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-title {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  margin-bottom: 3rem;
  color: var(--text);
}

.philosophy-body {
  max-width: 700px;
  font-size: 1.1rem;
  line-height: 1.9;
}

.philosophy-body p {
  margin-bottom: 1.5rem;
}

.section-divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 3rem;
}

.section-divider hr {
  border: none;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

.services-section {
  padding: 4rem 3rem 6rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-question {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 500;
  font-style: italic;
  margin-bottom: 4rem;
  color: var(--text);
}

.service-item {
  margin-bottom: 3.5rem;
  max-width: 750px;
}

.service-item h3 {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text);
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.85;
  color: var(--text-secondary);
}

/* ============================
   CLIENTS PAGE
   ============================ */

.clients-page-header {
  padding-top: 10rem;
  padding-bottom: 2rem;
  padding-left: 3rem;
  padding-right: 3rem;
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-page-title {
  font-family: var(--serif);
  font-size: clamp(3rem, 6vw, 6rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.clients-page-subtitle {
  font-family: var(--sans);
  font-size: 1rem;
  color: var(--text-secondary);
  margin-top: 0.5rem;
  font-weight: 400;
}

.clients-grid {
  padding: 2rem 3rem 6rem;
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2.5rem 3rem;
}

.client-card h3 {
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.6rem;
  color: var(--text);
}

.client-card p {
  font-family: var(--sans);
  font-size: 0.95rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ============================
   CONTACT PAGE
   ============================ */

.contact-hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 3rem;
}

.contact-title {
  font-family: var(--serif);
  font-size: clamp(5rem, 18vw, 20rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
  color: var(--text);
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  gap: 3rem;
}

.contact-links a {
  font-family: var(--sans);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}

.contact-links a:hover {
  color: var(--text);
  border-bottom-color: var(--text);
  opacity: 1;
}

/* ============================
   FOOTER
   ============================ */

.site-footer {
  padding: 3rem;
  border-top: 1px solid rgba(26, 26, 26, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-text {
  font-size: 0.8rem;
  color: var(--text-secondary);
}

/* ============================
   PAGE TRANSITIONS / ANIMATION
   ============================ */

.fade-in {
  opacity: 0;
  transform: translateY(20px);
  animation: fadeInUp 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.fade-in-delay-1 { animation-delay: 0.15s; }
.fade-in-delay-2 { animation-delay: 0.3s; }
.fade-in-delay-3 { animation-delay: 0.45s; }

@keyframes fadeInUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ============================
   RESPONSIVE
   ============================ */

@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: 1.25rem 1.5rem;
  }

  .desktop-nav {
    display: none;
  }

  .hamburger {
    display: block;
  }

  .hero {
    padding: 7rem 1.5rem 3rem;
    min-height: 50vh;
    align-items: center;
  }

  .media-showcase {
    padding: 1.5rem;
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .media-block--tall,
  .media-block--medium {
    height: 220px;
  }

  .about-section {
    padding: 4rem 1.5rem;
  }

  .founder-letter {
    padding: 8rem 1.5rem 4rem;
  }

  .philosophy-section {
    padding: 8rem 1.5rem 3rem;
  }

  .services-section {
    padding: 3rem 1.5rem 4rem;
  }

  .section-divider {
    padding: 0 1.5rem;
  }

  .clients-page-header {
    padding: 8rem 1.5rem 1.5rem;
  }

  .clients-grid {
    padding: 1.5rem;
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .contact-title {
    font-size: clamp(4rem, 20vw, 10rem);
  }

  .contact-links {
    flex-direction: column;
    gap: 1.5rem;
    align-items: center;
  }

  .site-footer {
    padding: 2rem 1.5rem;
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }

  .marquee-item {
    font-size: clamp(1.2rem, 5vw, 2rem);
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 2rem;
  }

  .founder-letter .letter-body p:first-of-type::first-letter {
    font-size: 3rem;
  }
}

